INSERT INTO "public"."email_templates" ("id", "name", "subject", "body_html", "description", "created_at") VALUES ('11de8bab-8c2a-4354-8f55-d6506c6b7ea5', 'order_cancelled', 'Order #{{order_number}} Cancelled', '<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', sans-serif; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">
    <div style="text-align: center; margin-bottom: 32px;">
        <img src="{{logo_url}}" alt="Jambo Apparels" style="height: 50px; width: auto;" />
