INSERT INTO "public"."user_addresses" ("id", "user_id", "label", "address1", "address2", "city", "postcode", "country", "phone", "is_default", "created_at") VALUES ('2b2d16ee-d6be-4bf1-9f0f-033c6c7e49cb', '1ee9d035-9532-4f08-94d1-6af28167a899', 'Saved Address', 'm85juhc0uk@daouse.com', 'Peace be with you, 46vvl0oekh.', 'Resilient Tax Logic (Checkout.tsx): Added a normalization step: if the taxRate from settings is greater than or equal to 1, it is automatically divided by 100 to get the correct decimal for calculations. Updated the display label to correctly show the percentage (e.g., "20%"). Order Summary Consistency: Verified that the taxAmount calculation (VAT inclusive) follows the standard UK/EU formula: (Total / (1 + Rate)) * Rate. Ensured the "Order Summary" visuals remain high-quality with product images and clear pricing tiers.', 'Resilient Tax Logic (Checkout.tsx): Added a normalization step: if the taxRate from settings is greater than or equal to 1, it is automatically divided by 100 to get the correct decimal for calculations. Updated the display label to correctly show the percentage (e.g., "20%"). Order Summary Consistency: Verified that the taxAmount calculation (VAT inclusive) follows the standard UK/EU formula: (Total / (1 + Rate)) * Rate. Ensured the "Order Summary" visuals remain high-quality with product images and clear pricing tiers.', 'United Kingdom', 'Estimated Tax (2000%)', 'false', '2026-01-22 22:02:32.142691+00'), ('9b4b0150-1ac8-40ff-9376-7c3e612fb812', '199df76a-2324-480a-8f63-2e20af94036a', 'Saved Address', '123 Uk Lane', null, 'Leeds', '01000', 'United Kingdom', '00111001100', 'false', '2026-01-23 06:07:38.579183+00'), ('c97baf31-eaca-4a84-896a-7726a562c695', '5633d1b8-5c06-4e5b-bc42-56501580235c', 'Saved Address', 'Apartment 3 160 Toller Lane Bradford West', null, 'Yorkshire, England', 'CM15 0DA', 'United Kingdom', '9999999999', 'false', '2026-02-05 22:01:16.030235+00');
